def serialize(root, val, left, right):
    out = []
    queue = [root]
    for u in queue:  # the list grows while we walk it
        if u == -1:
            out.append(-1)
        else:
            out.append(val[u])
            queue.append(left[u])
            queue.append(right[u])
    while out and out[-1] == -1:
        out.pop()
    return out


def build_balanced(a):
    # node i is a[i]; the root of every range lo..hi is the lower middle index
    n = len(a)
    left, right = [-1] * n, [-1] * n
    root = -1
    stack = [(0, n - 1, -1, 0)]
    while stack:
        lo, hi, parent, side = stack.pop()
        if lo > hi:
            continue
        m = (lo + hi) // 2
        if parent == -1:
            root = m
        elif side == 0:
            left[parent] = m
        else:
            right[parent] = m
        stack.append((lo, m - 1, m, 0))
        stack.append((m + 1, hi, m, 1))
    return serialize(root, a, left, right)


def sortedArrayToBst(nums):
    return build_balanced(nums)
